//! Generic Document identity is independent from the HTML/XML document flag.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn text_whole_native_getter_text_cdata_owners_and_contiguous_tree_boundaries(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var d=Object.getOwnPropertyDescriptor(Text.prototype,'wholeText'),get=d.get;if(get.name!=='get wholeText'||get.length!==0||d.set!==undefined||!d.enumerable||!d.configurable||Object.hasOwn(CDATASection.prototype,'wholeText'))throw 'canonical Text getter';var xml=document.implementation.createDocument(null,''),generic=new Document(),html=document.implementation.createHTMLDocument('owner'),template=xml.createElementNS('http://www.w3.org/1999/xhtml','template').content.ownerDocument;for(var owner of [document,html,xml,generic,template]){var parent=owner.createElementNS('http://www.w3.org/1999/xhtml','span'),before=owner.createTextNode('before'),stop=owner.createComment('stop'),a=owner.createTextNode('A'),empty=owner.createTextNode(''),b=owner===xml||owner===generic||owner===template?owner.createCDATASection('B'):owner.createTextNode('B'),c=owner.createTextNode('C'),pi=owner.createProcessingInstruction('target','stop'),after=owner.createTextNode('D'),element=owner.createElementNS('http://www.w3.org/1999/xhtml','b'),tail=owner.createTextNode('E');element.appendChild(owner.createTextNode('inside'));for(var node of [before,stop,a,empty,b,c,pi,after,element,tail])parent.appendChild(node);for(var node of [a,empty,b,c]){if(node.wholeText!=='ABC'||get.call(node)!=='ABC'||node.ownerDocument!==owner||node.parentNode!==parent)throw 'genuine contiguous Text and CDATA owner data';}if(before.wholeText!=='before'||after.wholeText!=='D'||tail.wholeText!=='E'||element.firstChild.wholeText!=='inside')throw 'comment PI Element and nested-tree boundaries';b.replaceData(0,1,'x');if(a.wholeText!=='AxC'||b.data!=='x'||a.data!=='A'||empty.data!=='')throw 'current data without source concatenation mutation';parent.removeChild(pi);if(after.wholeText!=='AxCD'||a.wholeText!=='AxCD')throw 'current sibling removal';parent.insertBefore(pi,after);if(after.wholeText!=='D'||a.wholeText!=='AxC')throw 'current sibling insertion';}for(var bad of [document,document.body,document.createAttribute('x'),document.createComment('x'),document.createProcessingInstruction('x','data'),{},Text.prototype,null]){var caught=false;try{get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'Text-only native getter brand';}
"#);
}
#[test]
fn text_whole_exact_joined_surrogates_clone_independence_and_same_identity_promotion(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var owner=new Document(),parent=owner.createElementNS('http://www.w3.org/1999/xhtml','span'),a=owner.createTextNode('A\ud83d'),b=owner.createCDATASection('\ude00B'),empty=owner.createTextNode(''),lone=owner.createTextNode('\ud800'),tail=owner.createTextNode('C');for(var node of [a,b,empty,lone,tail])parent.appendChild(node);var original='A\ud83d\ude00B\ud800C',copy=parent.cloneNode(true),list=parent.childNodes;if(a.wholeText!==original||b.wholeText!==original||lone.wholeText!==original||a.data!=='A\ud83d'||b.data!=='\ude00B'||lone.data!=='\ud800'||copy.firstChild.wholeText!==original)throw 'exact cross-node units and unchanged source parts';a.appendData('X');var current='A\ud83dX\ude00B\ud800C';if(a.wholeText!==current||copy.firstChild.wholeText!==original)throw 'current joined values and independent clone';var held=a;document.body.appendChild(parent);if(parent.firstChild!==held||parent.childNodes!==list||a.ownerDocument!==document||b.ownerDocument!==document||a.wholeText!==current||b.wholeText!==current||copy.firstChild.wholeText!==original)throw 'same native aliases through actual promotion';
"#);
}
#[test]
fn text_whole_template_fragment_and_parser_import_boundaries_use_actual_nodes(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var owner=document.implementation.createHTMLDocument('template owner'),holder=owner.createDocumentFragment(),host=owner.createElement('template'),left=owner.createTextNode('L'),right=owner.createTextNode('R'),ordinary=owner.createTextNode('host');holder.appendChild(left);holder.appendChild(host);holder.appendChild(right);host.appendChild(ordinary);var content=host.content,contentsOwner=content.ownerDocument,a=contentsOwner.createTextNode('A'),b=contentsOwner.createTextNode('B'),nested=contentsOwner.createElement('template');content.appendChild(a);content.appendChild(b);content.appendChild(nested);nested.content.appendChild(contentsOwner.createTextNode('inner'));if(left.wholeText!=='L'||right.wholeText!=='R'||ordinary.wholeText!=='host'||a.wholeText!=='AB'||b.wholeText!=='AB'||nested.content.firstChild.wholeText!=='inner'||ordinary.parentNode!==host||a.parentNode!==content)throw 'dedicated content and ordinary host children stay separate';var parsed=new DOMParser().parseFromString('<html><body><span>A<!--stop-->B</span></body></html>','text/html'),root=parsed.body.firstChild,first=root.firstChild,last=root.lastChild;root.appendChild(parsed.createTextNode('C'));var imported=document.importNode(root,true);if(first.wholeText!=='A'||last.wholeText!=='BC'||imported.firstChild.wholeText!=='A'||imported.lastChild.wholeText!=='BC'||root.lastChild.ownerDocument!==parsed||imported.lastChild.ownerDocument!==document)throw 'actual parsed and imported source identity';");
}
#[test]
fn text_whole_readonly_query_preserves_parts_ranges_views_and_observation(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var parent=document.createElement('span'),a=document.createTextNode('A\ud83d'),b=document.createTextNode('\ude00B');parent.appendChild(a);parent.appendChild(b);var view=parent.childNodes,range=document.createRange();range.setStart(a,1);range.setEnd(b,1);var watch=new MutationObserver(function(){});watch.observe(parent,{subtree:true,characterData:true,childList:true});for(var i=0;i<10;i++){if(a.wholeText!=='A\ud83d\ude00B'||b.wholeText!=='A\ud83d\ude00B')throw 'joined query result';}if(a.data!=='A\ud83d'||b.data!=='\ude00B'||view.length!==2||view[0]!==a||view[1]!==b||a.nextSibling!==b||range.startContainer!==a||range.endContainer!==b||range.startOffset!==1||range.endOffset!==1||watch.takeRecords().length)throw 'read does not normalize data or mutate Range/list/observers';"#);
}
#[test]
fn text_whole_saved_child_getter_origin_precedes_native_data_read(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var get=Object.getOwnPropertyDescriptor(frame.contentWindow.Text.prototype,'wholeText').get,text=document.createTextNode('held'),calls=0;if(get.call(text,{toString:function(){calls++;return 'ignored';}})!=='held'||calls)throw 'genuine captured getter with no argument conversion';");page.set_location(&crate::navigation::address("https://other-text-whole.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"get.call(text);").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(calls||text.data!=='held')throw 'origin refusal leaves actual data';");
}
